window.__BUNDLE__={"generatedAt":"2026-08-25T02:11:39.442727+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-08-18","archiveCutoff":"2021-08-26","addedToday":396,"addedThisRun":396,"fetchStats":{"hf":186,"arxiv":1444,"total":1630},"freshness":{"latestPaperDate":"2026-08-24","latestPublishedDate":"2026-08-24","latestBatchCount":380,"newInLast24h":646,"newInLast48h":646},"historyTotal":8603,"topicCounts":{"Multi-Agent":1666,"Evaluation":4337,"Planning":793,"Memory":197,"Code Agent":461,"Interpretability":285,"Agentic RAG":916,"Agentic Search":1108,"RL for LLM":684,"Reasoning":2769,"Hallucination":538,"Post-Training":1271,"Alignment":1125,"World Model":93,"Tool Use":999,"Agent Safety":1957,"Computer Use":197,"Reflection":383,"VLM Training":390,"LLM Training":924,"Fine-tuning":1252,"Multimodal Agent":55,"Agent Framework":608,"Error Attribution":77,"Data Engine":186},"count":36,"recentTotal":1607,"archiveCount":0,"archiveTotal":6996,"sources":{"hf":58,"arxiv":1545,"semanticScholar":4},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"pdf":"https://arxiv.org/pdf/2608.21278.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"CLEAR: Continuous Latent Adapter Routing for Utility-Preserving LLM Safety Alignment","url":"https://arxiv.org/abs/2608.21278","topics":["Agent Safety","LLM Training","Evaluation","Alignment","Fine-tuning"],"authors":["Chengxiao Wang","Enyi Jiang","Xiaojing Liao","Sanmi Koyejo"],"source":"hf","arxiv":"https://arxiv.org/abs/2608.21278","submittedDate":"2026-08-21","id":"arxiv:2608.21278","tags":["Agent Safety","LLM Training","Evaluation","Alignment","Fine-tuning"],"hfUrl":"https://huggingface.co/papers/2608.21278","upvotes":3,"abstract":"Improving the safety of large language models (LLMs) often comes at the expense of utility, as globally applied safety tuning may affect model responses to both harmful and benign inputs. We propose \\textbf{C}ontinuous \\textbf{L}at\\textbf{E}nt \\textbf{A}dapter \\textbf{R}outing (CLEAR), a conditional safety adaptation framework that uses a lightweight hidden-state gate to continuously control the activation strength of a safety low-rank adapter. CLEAR aims to reduce harmful completions while avoiding unnecessary changes to the frozen backbone that could degrade performance on benign prompts. Experiments on widely used safety and utility benchmarks show that CLEAR improves robustness on HarmBench while reducing the utility degradation observed with globally applied safety tuning such as SFT or standard low-rank adaptation (LoRA). On Llama-3-8B-Instruct, CLEAR reduces HarmBench ASR from 32."},{"pdf":"https://arxiv.org/pdf/2608.21439.pdf","date":"2026-08-24","title":"WorldMind: Decoupled Game World Model for State-Aware NPC Behavior","url":"https://arxiv.org/abs/2608.21439","topics":["Planning","World Model"],"authors":["Zhiyang Deng","Boran Zhang","Danze Chen","Yeying Jin"],"source":"hf","arxiv":"https://arxiv.org/abs/2608.21439","id":"arxiv:2608.21439","tags":["Planning","World Model"],"hfUrl":"https://huggingface.co/papers/2608.21439","upvotes":3,"abstract":"Game world models have recently demonstrated promising capabilities in generating visually coherent and action-controllable gameplay videos. However, non-player character (NPC) behavior in existing models is either implicitly entangled with video generation or explicitly prescribed through external control signals. Consequently, a game world model has to jointly understand the state, plan the NPC's response and render its visual outcome, limiting its ability to produce responsive and state-aware NPC behavior. The challenge lies in the lack of an explicit interface for state-grounded decision-making. To this end, we introduce WorldMind, to our knowledge the first decoupled framework for state-aware NPC behavior in game world models. WorldMind separates interactive world modeling into four layers: an Understanding Layer that constructs a compact state from generated frames; a Decision Laye"},{"pdf":"https://arxiv.org/pdf/2608.21156.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"Graph Engineering in the Era of LLM Agents: From Individual Intelligence to System Intelligence","url":"https://arxiv.org/abs/2608.21156","topics":["Reflection"],"authors":["Yuyuan Feng","Zhishang Xiang","Chaobin Yang","Qichao Ma","Zerui Chen","Yujing Zhang","Ke Huang","Chuanjie Wu","Zhaoxu Liu","Yili Wang","Xin He","Jiapu Wang","Zijin Hong","Hao Chen","Yuanchen Bei","Kun Wang","Shengyuan Chen","Ningyu Zhang","Enyan Dai","Linhao Luo","Qingyi Pan","Qi Wang","Wenqi Fan","Guangjing Wang","Na Zou","Yangqiu Song","Xin Wang","Zechao Li","Xia Hu","Qing Li","Xiao Huang","Zhihong Zhang","Jinsong Su","Qinggang Zhang","Yi Chang"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.21156","submittedDate":"2026-08-21","id":"arxiv:2608.21156","tags":["Reflection"],"hfUrl":"https://huggingface.co/papers/2608.21156","upvotes":34,"abstract":"LLMs have evolved from language generators to autonomous agents capable of complex, long-horizon tasks. This evolution has produced paradigms including Prompt Engineering to elicit model capabilities, Context Engineering to manage information access, Harness Engineering to organize external tools and resources, and Loop Engineering to support continual reflection and self-improvement. Yet as tasks grow more complex, individual intelligence faces a fundamental limit: many tasks require heterogeneous expertise, interdependent subtasks, parallel execution, independent verification, and persistent state, exceeding any single agent's organizational capacity. Augmenting one agent's capabilities or context cannot resolve this architectural mismatch; intelligence must instead be distributed across specialized agents and organized at the system level. We call this System Intelligence: an agent sy"},{"pdf":"https://arxiv.org/pdf/2608.21360.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"OmniAssistBench: Assistant-style Interaction Benchmark for Omni-LLMs","url":"https://arxiv.org/abs/2608.21360","topics":["Evaluation"],"authors":["Xianyun Sun","Chaoyou Fu","Zhengye Zhang","Feiyang Duan","Qingyuan Cao","Yonghui Niu","Sihang Yuan","Ge Zhang","Caifeng Shan"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.21360","submittedDate":"2026-08-21","id":"arxiv:2608.21360","tags":["Evaluation"],"hfUrl":"https://huggingface.co/papers/2608.21360","upvotes":27,"abstract":"Recent omni-modal large language models (Omni-LLMs) show great potential as real-time video assistants, which continuously perceive environments and guide users to achieve specific goals. Unlike traditional passive video understanding, interactive assistants should actively combine visual states, user goals, and prior knowledge to provide effective help. Evaluating this is rather challenging, as the model's unpredictable response dynamically changes the user's subsequent actions, which static offline datasets cannot accommodate. To address this bottleneck, we introduce OmniAssistBench. To solve the issue of diverging interaction paths where the same user goal can be achieved through various methods, we provide models with predefined priors derived from the source video, requiring them to guide users along the exact same routes. Since real interaction videos are rare, we construct the dat"},{"pdf":"https://arxiv.org/pdf/2608.20886.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"EviRank: Structured Relevance Evidence for Multimodal Image Re-ranking","url":"https://arxiv.org/abs/2608.20886","topics":["Reasoning","Hallucination","Evaluation"],"authors":["Enjun Du","Siyi Liu","Zirong Chen","Xinyu Zuo","Jinwen Luo","Ruiwen Tao","Lisheng Duan","Haijin Liang","Jin Ma","Junfu Pu","Yongqi Zhang"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.20886","submittedDate":"2026-08-21","id":"arxiv:2608.20886","tags":["Reasoning","Hallucination","Evaluation"],"hfUrl":"https://huggingface.co/papers/2608.20886","upvotes":11,"abstract":"Real-world image search queries are multimodal and compositional: ``find this shirt in pink'' specifies an entity to retain, an attribute to modify, and context to ignore. Yet existing re-rankers either compress such multifaceted relevance into an opaque embedding or rely on free-form chain-of-thought that easily omits or hallucinates fine-grained constraints. Drawing on rubric- and checklist-based evaluation from NLP, we recast multimodal image re-ranking as a semantic constraint satisfaction problem and propose EviRank, which parses any query - text-only, image-only, or composed - into a unified evidence package: typed criteria across six semantic slots (e.g., entities, attributes, relations), each labelled required, forbidden, or ignorable. Re-ranking then reduces to evidence-conditioned verification, combining deterministic rubric scoring and evidence-grounded listwise comparison in "},{"pdf":"https://arxiv.org/pdf/2608.20634.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"AgentMercury: Your Agent Can Synthesize Verifiable Environments for Business Scenarios at scale","url":"https://arxiv.org/abs/2608.20634","topics":["Tool Use","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"authors":["Minbyul Jeong","Chanwoong Yoon"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.20634","submittedDate":"2026-08-21","id":"arxiv:2608.20634","tags":["Tool Use","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"hfUrl":"https://huggingface.co/papers/2608.20634","upvotes":7,"abstract":"Agents learn to act through interaction with environments, yet the environments used for training are often manually constructed or synthesized around predefined tasks and benchmarks. This task-centric paradigm makes it difficult to scale environments that reflect realistic and evolving workflows where diverse tasks can naturally emerge from the underlying world. We introduce AgentMercury, a scalable framework for synthesizing executable environments from high-level business scenarios. Rather than constructing an environment for a specific task, AgentMercury first instantiates a persistent world with entities, services, tools, state, and executable cross-service invariants, from which diverse tasks and interaction trajectories can subsequently emerge. We construct 4,783 executable environments spanning 14 industries and 50 countries, and use them as training substrates for reinforcement "},{"pdf":"https://arxiv.org/pdf/2608.20707.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"Towards Faithful Simulation of Human Shopping Behavior","url":"https://arxiv.org/abs/2608.20707","topics":["VLM Training","Memory","Evaluation","RL for LLM"],"authors":["Jiakai Tang","Yan Mi","Jing Yu","Yang Zhang","See-Kiong Ng","Qi Cao","Fei Sun","Xu Chen","Wen Chen","Jian Wu","Han Zhu","Bo Zheng"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.20707","submittedDate":"2026-08-21","id":"arxiv:2608.20707","tags":["VLM Training","Memory","Evaluation","RL for LLM"],"hfUrl":"https://huggingface.co/papers/2608.20707","upvotes":5,"abstract":"Simulating realistic user shopping behavior underpins offline evaluation and reinforcement learning in e-commerce scenarios. While recent LLM- and VLM-based simulators have made encouraging progress, reproducing a real browsing session remains difficult for two reasons. (i) Memory Challenge: a shopping session spans dozens of pages, yet existing agents either discard long-range observation histories, losing the evolving user state, or naively concatenate them, overwhelming the context window and even degrading simulation quality. (ii) Optimization Challenge: current user simulators are typically supervised to match each logged action via imitation or step-level rewards; the resulting sessions often display unrealistic patterns, such as over-exploration or excessive passivity, which per-step supervision can neither detect nor correct. To address the above challenges, we present RecVerse, "},{"pdf":"https://arxiv.org/pdf/2608.20438.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"Peer-Voted LLM-Agent Stress Tests Find Feed-Induced Lexical Convergence but No Reliable Matched-Exposure Advantage for Distributed Sources","url":"https://arxiv.org/abs/2608.20438","topics":["Evaluation"],"authors":["Rana Muhammad Usman","Dominic Williamson"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.20438","submittedDate":"2026-08-20","id":"arxiv:2608.20438","tags":["Evaluation"],"hfUrl":"https://huggingface.co/papers/2608.20438","upvotes":3,"abstract":"Population-level behavior in large-language-model (LLM) agents cannot be characterized by single-agent benchmarks. We introduce PV-SST, a peer-voted social-platform testbed, and report a separately frozen, preregistered matched-exposure experiment spanning four topics, four unused seeds, four open-weight model families, and three prespecified larger variants. The experiment comprises 448 trials and 112 complete model-by-topic-by-seed blocks. Relative to a topic-only control, a feed of previous-round peer posts ranked by peer-generated likes increases final-round lexical similarity in both the four-family core panel (paired mean difference +0.0082 TF-IDF cosine units, 95% block-bootstrap CI [0.0043, 0.0121], randomization p=0.000105, n=64 blocks) and the three-variant size extension (+0.0109 [0.0069, 0.0151], p=0.000001, n=48). This contrast bundles peer-post exposure with ranking and the"},{"pdf":"https://arxiv.org/pdf/2608.20364.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"Hadith computational science in the age of large language models: a critical narrative review","url":"https://arxiv.org/abs/2608.20364","topics":["Evaluation"],"authors":["Md. Ashraful Haque","Riasat Islam"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.20364","submittedDate":"2026-06-18","id":"arxiv:2608.20364","tags":["Evaluation"],"hfUrl":"https://huggingface.co/papers/2608.20364","upvotes":2,"abstract":"We examine how hadith computational science is being reshaped by transformer models, retrieval-grounded pipelines, and large language models (LLMs). Recent reviews document growth in the literature, but they do not yet provide a critical account of which advances are methodologically robust, which remain benchmark-bound, and which unresolved problems still limit scholarly use. We address this gap through a critical narrative review that combines critique of existing reviews, paper-level appraisal of representative original studies, and synthesis of Islamic scholar and domain-expert perspectives on authenticity, authority, and responsible use. We find uneven progress. Data resources have expanded, segmentation tasks have matured, narrator and source-verification problems are better formalized, and LLM-assisted workflows now support corpus-scale enrichment, multilingual access, and grounde"},{"pdf":"https://arxiv.org/pdf/2608.21305.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"Re$^3$Cap: Retrieval-Guided Refinement for Image Captioning Enhancement via Reinforcement Learning","url":"https://arxiv.org/abs/2608.21305","topics":["Post-Training","LLM Training","VLM Training","Reasoning","Hallucination","Evaluation","Fine-tuning","RL for LLM"],"authors":["Haonan Jia","Shichao Dong","Zenghui Sun","Jiawen Zheng","Ziqi Miao","Gege Shi","Qiuyu Zhao","Jinsong Lan","Xiaoyong Zhu","Bo Zheng"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.21305","submittedDate":"2026-08-21","id":"arxiv:2608.21305","tags":["Post-Training","LLM Training","VLM Training","Reasoning","Hallucination"],"upvotes":0,"abstract":"Reinforcement Learning (RL) has demonstrated significant gains in image captioning, yet it is still limited in encouraging Large Vision-Language Models (LVLMs) to explore novel reasoning strategies. This limitation leads to a performance gap between RL and Supervised Fine-Tuning (SFT). In this paper, we argue that multi-modal retrieval can serve as an effective reasoning signal for caption refinement. Based on this insight, we present the Retrieval-Guided Refinement for Image Captioning (Re$^3$Cap), a retrieval-guided reasoning strategy that enhances image captioning without requiring additional annotations. Instantiated by Caption Refinement Suggester (CRS) and Caption Quality Assessor (CQA), this strategy identifies hallucinations and omissions in image captions, leading to more accurate and detailed descriptions. Extensive experiments demonstrate the superiority of our method in image"},{"pdf":"https://arxiv.org/pdf/2608.20699.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"ArtiMo: Agent-Driven Articulated Mesh Animation","url":"https://arxiv.org/abs/2608.20699","topics":["LLM Training","VLM Training","Reasoning","Planning","Evaluation","Fine-tuning","Reflection"],"authors":["Chunyu Zou","Peng Dai","Yi-Hua Huang","Ze Yuan","Jingwei Huang","Yeming Yao","Xiaojuan Qi"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.20699","submittedDate":"2026-08-21","id":"arxiv:2608.20699","tags":["LLM Training","VLM Training","Reasoning","Planning","Evaluation"],"upvotes":0,"abstract":"Animating articulated 3D meshes via text requires satisfying strict kinematic constraints, modeling causal interactions between parts, and achieving instruction fidelity. Due to the absence of task-specific training data and explicit articulation supervision, existing data-driven mesh animation methods are largely inapplicable to this setting. To address this, we propose ArtiMo, a novel agent-driven framework for text-guided articulated mesh animation. Operating in a zero-shot manner, ArtiMo develops an agentic pipeline powered by Large Language and Vision-Language Models (LLMs/VLMs) to orchestrate motion generation. By synergizing the explicit kinematic constraints of URDF with the agent's reasoning and planning capabilities, it effectively produces causally coherent part motions and interactions without requiring model fine-tuning. To ensure motion correctness, the agent additionally u"},{"pdf":"https://arxiv.org/pdf/2608.20771.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"CAS: Conformalized Agentic Search via Adaptive Retrieval and Policy Weighting","url":"https://arxiv.org/abs/2608.20771","topics":["Agentic Search","Post-Training","Reasoning","Hallucination","Fine-tuning","RL for LLM"],"authors":["Zixi Zhu","Jiayuan Su","Jian Zhang","Yu Lin","Hongwei Wang"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.20771","submittedDate":"2026-08-21","id":"arxiv:2608.20771","tags":["Agentic Search","Post-Training","Reasoning","Hallucination","Fine-tuning"],"upvotes":0,"abstract":"Search Agents face a severe reliability crisis during reinforcement learning (RL) fine-tuning. Heuristic Top-K retrieval often causes critical evidence loss or noise inclusion, while over-confidence induced by progressive RL leads to hallucinated answers and redundant searches. To build highly reliable agents, we introduce Conformal Prediction (CP) and propose Conformalized Agentic Search (CAS). This framework establishes reliability guarantees on both the retrieval and training sides: on the retrieval side, an Adaptive Prediction Set (APS), a specific CP realization, translates statistical coverage into dynamic document truncation to construct prediction sets that are adaptive in size; on the training side, Adaptive Conformal Inference (ACI), a dynamic CP algorithm, dynamically constructs prediction sets with controllable coverage to quantify answer confidence, which is then used to pen"},{"pdf":"https://arxiv.org/pdf/2608.23493.pdf","date":"2026-08-24","title":"SRPO: Self-Reflective Policy Optimization for Long-Horizon Reasoning","url":"https://arxiv.org/abs/2608.23493","topics":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning","Reflection"],"authors":["Jialong Liu","Yuling Shi","Ning Yang","Xiaodong Gu","Zuchao Li"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.23493","id":"arxiv:2608.23493","tags":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"abstract":"Self-reflection is a powerful mechanism for credit assignment in human learning, converting sparse outcome feedback into actionable guidance. However, its potential for post-training Large Language Models (LLMs) remains underexplored. We propose Self-Reflective Policy Optimization (SRPO), a framework that internalizes this capability. SRPO enables LLMs to analyze their own completed trajectories, synthesize errors into concise \"reflection patches,\" and use reflection-conditioned teacher scores on student on-policy rollouts as dense token-level training signals. This process effectively transforms sparse terminal supervision into dense, token-level learning signals without requiring external critics, separate reward models, or larger teacher models. We demonstrate that SRPO achieves state-of-the-art performance across mathematical reasoning and long-horizon agentic benchmarks with excepti"},{"pdf":"https://arxiv.org/pdf/2608.21170.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"Is Visual Prompting All You Need? Studying VLM Spatial Reasoning under Progressive Visual Scaffolds","url":"https://arxiv.org/abs/2608.21170","topics":["Post-Training","VLM Training","Reasoning","Planning","Evaluation"],"authors":["Lars Benedikt Kaesberg","Tianyu Yang","Florian Valentin Wunderlich","Terry Ruas","Jan Philip Wahle","Daniel Kurzawe","Bela Gipp"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.21170","submittedDate":"2026-08-21","id":"arxiv:2608.21170","tags":["Post-Training","VLM Training","Reasoning","Planning","Evaluation"],"upvotes":0,"abstract":"Vision-language models (VLMs) have advanced rapidly in multimodal reasoning, yet recent work shows that their failures often reflect an interaction between visual grounding and downstream reasoning. What remains less clear is how the visual presentation of a task shapes model performance and failure modes when the underlying reasoning problem is unchanged. We study this question in SPaRC, a benchmark for grid-based visual spatial planning, by introducing lightweight input-side scaffolds that preserve the visual modality while making spatial structure more accessible. Across multiple VLMs, these scaffolds improve task accuracy over the original visual setting by up to 34.0 percentage points and further complement GRPO-based training, yielding up to 4.6 additional accuracy points compared with near-zero gains on the original visual input. Analyses on both end-to-end task solving and object"},{"pdf":"https://arxiv.org/pdf/2608.20627.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"When Failures Propagate: Causal Failure Attribution in Agentic Retrieval-Augmented Generation","url":"https://arxiv.org/abs/2608.20627","topics":["Agentic RAG","Agentic Search","Error Attribution","Reasoning","Evaluation"],"authors":["Lauren Pothuru"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.20627","submittedDate":"2026-08-20","id":"arxiv:2608.20627","tags":["Agentic RAG","Agentic Search","Error Attribution","Reasoning","Evaluation"],"upvotes":0,"abstract":"Agentic retrieval-augmented generation (RAG) interleaves retrieval, reasoning, and answer generation across multiple hops. A retrieval error at hop 1 can surface only as a wrong answer at hop 3, while later retrieval can also repair the trajectory. This paper introduces AgenticRAG-FP, an interventional benchmark for causal failure attribution in agentic RAG. The benchmark injects a certified fault at a specified hop, re-executes the downstream trajectory, and evaluates diagnosers against the known intervention. Its central question is whether a post-hoc trace still identifies the injected hop after the suffix changes. In the completed strict dense Claude Haiku 4.5 sweep on 80 three-hop MuSiQue questions, coverage-based diagnosis is 0.91 at hop 1 and 0.00 at hops 2 and 3 (n=43,36,21 failed trajectories). A smaller content-corruption study changes an answer-bearing or bridge fact in topica"},{"pdf":"https://arxiv.org/pdf/2608.20381.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"EditPPT: Faithful Long-Deck Slide Editing via Structured Tool-Using Multi-Agent with Dual-Modal Validators","url":"https://arxiv.org/abs/2608.20381","topics":["Agent Safety","Multi-Agent","Code Agent","Evaluation","Agent Framework"],"authors":["Jiheon Kim","Kyudan Jung","Jaegul Choo"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.20381","submittedDate":"2026-06-29","id":"arxiv:2608.20381","tags":["Agent Safety","Multi-Agent","Code Agent","Evaluation","Agent Framework"],"upvotes":0,"abstract":"Automating slide editing requires simultaneously satisfying modification accuracy, preservation fidelity, and robustness to deck length. Existing LLM-based systems often fail on real-world presentation files because they rely on idealized intermediate representations or open-ended code generation, which are prone to cascading errors in long decks. We introduce EditPPT, a multi-agent framework that reformulates slide editing as a constrained tool-selection problem. By executing localized shape-level operations through the native PowerPoint COM interface, EditPPT narrows the LLM action space while preserving the application-resolved structure of user-authored decks. By separating validation across modalities, our dual-modal validation provides more robust assessment of both instruction fidelity and visual quality. We also present DeckEdit-Bench, a benchmark with 28 human-authored decks, 58"},{"pdf":"https://arxiv.org/pdf/2608.20492.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"Annotations as Rollouts: Efficient and Scalable Reinforcement Learning for Video MLLMs","url":"https://arxiv.org/abs/2608.20492","topics":["Post-Training","LLM Training","Reasoning","Evaluation","RL for LLM"],"authors":["Yunheng Li","Guohong Mu","Hao Li","Shengsheng Qian","Dingwen Zhang","Qibin Hou","Ming-Ming Cheng"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.20492","submittedDate":"2026-08-20","id":"arxiv:2608.20492","tags":["Post-Training","LLM Training","Reasoning","Evaluation","RL for LLM"],"upvotes":0,"abstract":"Multimodal large language models (MLLMs) have become a prevailing paradigm for unified video perception. However, post-training on large multi-task datasets remains challenging, as existing reinforcement learning methods sample on-policy groups with few high-quality rollouts even with costly chain-of-thought (CoT) generation. In this paper, we study the sample efficiency and scalability of RL post-training for video MLLMs and introduce OraRL. We identify an overlooked role for annotations: Beyond scoring rollouts, each can enter its on-policy group as an oracle rollout, a direct positive optimization target. Direct oracle integration, however, is nontrivial: a high-reward oracle raises the group baseline and inverts otherwise positive policy advantages, a failure we term advantage inversion. At the core of OraRL is a decoupled advantage estimator: policy rollouts determine an oracle-free"},{"pdf":"https://arxiv.org/pdf/2608.21180.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"Toward Vision Language Model-based Assessment of Clinical Quality and Usability of LGE-MR Images for Cardiac Ablation Planning","url":"https://arxiv.org/abs/2608.21180","topics":["VLM Training","Reasoning","Planning","Evaluation","Fine-tuning"],"authors":["Bipasha Kundu","Abhishek Chaturvedi","Axel W. E. Wismueller","Richard Simon","Cristian A. Linte"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.21180","submittedDate":"2026-08-21","id":"arxiv:2608.21180","tags":["VLM Training","Reasoning","Planning","Evaluation","Fine-tuning"],"upvotes":0,"abstract":"LGE cardiac MRI is widely used for left atrial fibrosis assessment and ablation planning in atrial fibrillation patients as knowledge of fibrotic tissue regions identified from LGE-MRI is critical for catheter ablation. Often, poor quality images used during ablation planning can cause mis-localization of ablation targets, directly impacting procedure safety and outcome. The decision of whether a scan meets the minimum quality threshold for ablation planning is currently made informally by the reviewing radiologist and is not captured by any automated system, yet it is arguably the most safety-critical output of the image quality assessment (IQA) process. However, variations in image quality caused by noise, motion artifacts, and poor boundary definition significantly compromise the reliability of downstream segmentation and clinical decision-making tasks. Manual quality assessment by ex"},{"pdf":"https://arxiv.org/pdf/2608.23329.pdf","date":"2026-08-24","title":"Thinking Beyond Videos: Unifying Video Reasoning and Deep Research for Open-World Video Agents","url":"https://arxiv.org/abs/2608.23329","topics":["LLM Training","Tool Use","Reasoning","Evaluation","Multimodal Agent"],"authors":["Wenqi Liu","Shijie Ma","Yunxiao Wang","Meng Liu","Qile Su","Han Liu","Bohan Hou","Xuanyu Zheng","Changyi Liu","Tianke Zhang","Haonan Fan","Kaiyu Jiang","Yingxin Li","Jiankang Chen","Xu Wang","Bin Wen","Tingting Gao","Han Li","Jianhua Yin","Yinwei Wei","Xuemeng Song"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.23329","id":"arxiv:2608.23329","tags":["LLM Training","Tool Use","Reasoning","Evaluation","Multimodal Agent"],"upvotes":0,"abstract":"Open-world video understanding often requires a model to locate sparse visual evidence and acquire external knowledge that is absent from the video and its parametric memory. While Thinking-with-Videos enables active temporal perception and Deep Research supports multi-step information seeking, the two capabilities are typically developed in isolation. We introduce VideoRover, a unified Video Deep Research framework that iteratively coordinates video cropping, multimodal search, and webpage browsing. Given a video-question pair, VideoRover uses each tool result to select the next action, so localized video clips guide external retrieval and retrieved evidence triggers further video inspection and verification. To develop this capability, we construct an automated data curation pipeline, producing 26K verified SFT trajectories and 3K challenging RL instances. We also introduce VideoRover-"},{"pdf":"https://arxiv.org/pdf/2608.23152.pdf","date":"2026-08-24","title":"Counter with Evidence! A Multi-Agent Memory Efficient Reasoning Framework for Hate Category Informed Counterspeech Generation","url":"https://arxiv.org/abs/2608.23152","topics":["Multi-Agent","Reasoning","Memory","Hallucination","Evaluation"],"authors":["Sujoy Nath","Aswini Kumar","Tanmoy Chakraborty"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.23152","id":"arxiv:2608.23152","tags":["Multi-Agent","Reasoning","Memory","Hallucination","Evaluation"],"upvotes":0,"abstract":"Counterspeech effectively neutralizes the impact of online hate. Although prior work explores automated counterspeech generation, it largely emphasizes stylistic control while treating hate speech as homogeneous, overlooking that distinct forms of abuse require fundamentally different counterspeech strategies. To address this gap, we introduce FIRE (Factuality Informed Multi-Agent Reasoning Framework) that first decomposes hate speech into one of the five distinct categories (misinformation, stereotype, conspiracy, dehumanizing, non-factual), and then maps it to a targeted counterspeech style. To facilitate FIRE, we curate FactualCS, a novel dataset of $4,784$ instances that provides the annotations regarding hate categories, reasoning traces, and evidence mappings, which are critical elements for grounded generation that are missing in prior work. A comprehensive evaluation across $28$ "},{"pdf":"https://arxiv.org/pdf/2608.22963.pdf","date":"2026-08-24","title":"Buried in Textual Debt: Context Pruning with Visual Evidence Preservation for MLLM Agents","url":"https://arxiv.org/abs/2608.22963","topics":["LLM Training","Tool Use","Reasoning","Evaluation","Fine-tuning"],"authors":["Yuchen Huang","Sijia Li","Jun Zhang","Yi R. Fung"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.22963","id":"arxiv:2608.22963","tags":["LLM Training","Tool Use","Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"abstract":"Multimodal Large Language Models (MLLMs) are increasingly deployed as multi-step agents, where explicit reasoning supports task decomposition and tool coordination but also accumulates self-generated text. Over long trajectories, this text can dominate the context and suppress visual evidence, creating textual debt. We observe that reasoning becomes redundant once task-relevant visual evidence is grounded, while stale hypotheses can misguide later inference when grounding remains uncertain. Pruning must therefore remove redundant text without discarding visual evidence. We propose SPARE, a Kullback--Leibler (KL)-guided framework for pruning accumulated reasoning in multimodal tool-use agents. SPARE uses a compact task-state summary as privileged diagnostic context. For each candidate segment, it replays the same model under the original and summary-conditioned contexts. Reverse-KL diverg"},{"pdf":"https://arxiv.org/pdf/2608.23265.pdf","date":"2026-08-24","title":"EvoWiki: Incremental State Overwriting and Traceable Question Answering for Cross-Meeting Knowledge Evolution","url":"https://arxiv.org/abs/2608.23265","topics":["Agentic RAG","Agentic Search","Reasoning","Hallucination","Evaluation"],"authors":["Dongsheng Chen","Tianyu Wang","Wenhui Que"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.23265","id":"arxiv:2608.23265","tags":["Agentic RAG","Agentic Search","Reasoning","Hallucination","Evaluation"],"upvotes":0,"abstract":"In long-term collaboration spanning multiple meetings, factual states such as decisions and risks are continually revised, overturned, and replaced. Existing long-context methods typically stack the entire history, while many RAG and structured-memory methods organize knowledge as static or append-only facts and rely on semantic relevance at read time. Without explicit modeling of knowledge lifecycles, these approaches may retain conflicting old and new states simultaneously or discard history, leading to stale retrieval and answers that are difficult to verify. We present EvoWiki, an incremental question-answering architecture for dynamic long-form text. EvoWiki decouples offline incremental construction (BUILD) from online structured reading (READ). BUILD captures the intra-meeting micro-evolution from proposal to decision and uses entity version chains and a fine-grained State-Overwri"},{"pdf":"https://arxiv.org/pdf/2608.22938.pdf","date":"2026-08-24","title":"Execution-Anchored Hallucination Calibration Reranking for Verilog Code Generation","url":"https://arxiv.org/abs/2608.22938","topics":["Agentic RAG","Agentic Search","Reasoning","Hallucination","Evaluation"],"authors":["Guang Yang","Xing Hu","Xiang Chen","Terry Yue Zhuo","Xin Xia"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.22938","id":"arxiv:2608.22938","tags":["Agentic RAG","Agentic Search","Reasoning","Hallucination","Evaluation"],"upvotes":0,"abstract":"Large Language Models (LLMs) have demonstrated remarkable capabilities in code generation, yet their performance degrades significantly on low-resource Hardware Description Languages such as Verilog. While multi-candidate sampling improves the likelihood of generating correct solutions, au-tomatically selecting the optimal candidate remains an open challenge. Through a systematic empirical study across nine models and two benchmarks, we identify two critical limitations:(1) existing execution-based reranking methods, which rely on testbench pass/fail outcomes, exhibit poor domain transferability due to low-quality generated testbenches; and (2) LLM-as-a-Judge suffers from reasoning hallucination, producing incon-sistent judgments for execution-equivalent code. These findings reveal two signal types with orthogonal errors: execution signals(deterministic but testbench coverage limited)and"},{"pdf":"https://arxiv.org/pdf/2608.23256.pdf","date":"2026-08-24","title":"Is Next-Chunk Reasoning RL Really Better than SFT? Revisiting Training Strategies under no-CoT Data","url":"https://arxiv.org/abs/2608.23256","topics":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"authors":["Yinhao Tang","Youqing Fang","Yanan Sun","Jiangning Liu","Ziyi Wang","Xun Zhao","Weiming Zhang","Bin Liu","Kuikun Liu","Wenwei Zhang","Kai Chen"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.23256","id":"arxiv:2608.23256","tags":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"abstract":"Recent work proposes next-chunk reasoning RL for leveraging no-CoT data---corpora such as worked solutions and textbook derivations that contain reasoning-rich content but lack explicit chain-of-thought annotations. The method trains a model to generate implicit reasoning traces and rewards them by their ability to predict the next chunk of text. While promising, existing evaluations primarily compare against conventional SFT baselines, leaving open whether the gains come from the RL formulation itself or from more effectively exposing the model to no-CoT data. We address this question with a controlled study of next-chunk reasoning RL and a simple but previously overlooked alternative: Mixed SFT, a single supervised fine-tuning stage that jointly trains on no-CoT and long-CoT data. Despite its simplicity, Mixed SFT achieves a clearly higher post-RLVR performance ceiling than next-chunk "},{"pdf":"https://arxiv.org/pdf/2608.22854.pdf","date":"2026-08-24","title":"Thinking at the Right Size: Amortized Distillation Across Post-Trained LLMs","url":"https://arxiv.org/abs/2608.22854","topics":["Post-Training","LLM Training","Reasoning","Alignment","Fine-tuning"],"authors":["Yan Zhou","Sara Kangaslahti","Jonathan Geuter","Nihal V. Nayak","Marco Fumero","Francesco Locatello","David Alvarez-Melis"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.22854","id":"arxiv:2608.22854","tags":["Post-Training","LLM Training","Reasoning","Alignment","Fine-tuning"],"upvotes":0,"abstract":"Practical deployment of large language models (LLMs) requires families of post-trained variants---instruction-tuned, reasoning-tuned, and chat-style models---each at multiple sizes to meet diverse latency and memory budgets. Producing each (variant, size) pair independently is prohibitive, so model families typically span only a handful of coarse-grained sizes per post-trained variant. Boomerang distillation (Kangaslahti et al., 2026) reduces this cost along the size axis for base models. Through model size interpolation, it constructs models of intermediate sizes from a single teacher-student pair without additional training. However, it still treats each post-trained variant as a separate object of optimization. We introduce ADAPT---Amortized Distillation Across Post-Trained LLMs---a framework for amortizing distillation across both axes of a model family: size and post-training varian"},{"pdf":"https://arxiv.org/pdf/2608.23497.pdf","date":"2026-08-24","title":"Mitigating Reasoning-Induced Misalignment via Safety-Direction Penalty","url":"https://arxiv.org/abs/2608.23497","topics":["Reasoning","Evaluation","Alignment","Interpretability","Fine-tuning"],"authors":["Yipeng Zhao","Qishun Yang","Shenzhe Zhu","Shu Yang","Di Wang"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.23497","id":"arxiv:2608.23497","tags":["Reasoning","Evaluation","Alignment","Interpretability","Fine-tuning"],"upvotes":0,"abstract":"Reasoning-Induced Misalignment, where fine-tuning on reasoning data containing no harmful content, including mathematics, code, and problem-solving with chain-of-thought traces can induce harmful behaviors of LLM, posing a serious challenge to the safety of LLM reasoning. Cross-architecture, cross-scale, and cross-dataset checks show that RIM does not always emerge. Previous work attributed RIM to neuron-level entanglement, but did not identify the geometry of the representation space underlying this entanglement or propose a training-time fix. We provide both: a representation-space analysis of RIM and the Safety-Direction Penalty (SDP), which penalizes movement along a learned safety direction during reasoning fine-tuning. The analysis extracts two activation-space directions, one encoding reasoning ability and the other safety behavior. These directions are coupled: fine-tuning that i"},{"pdf":"https://arxiv.org/pdf/2608.23476.pdf","date":"2026-08-24","title":"On the Threat Model of Weird Generalization and Emergent Misalignment","url":"https://arxiv.org/abs/2608.23476","topics":["LLM Training","Evaluation","Alignment","Fine-tuning","Data Engine"],"authors":["Miriam Wanner","Mark Dredze","William Walden"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.23476","id":"arxiv:2608.23476","tags":["LLM Training","Evaluation","Alignment","Fine-tuning","Data Engine"],"upvotes":0,"abstract":"Narrow fine-tuning on small, domain-specific datasets can produce broad and surprising changes in model behavior-a phenomenon called weird generalization (WG). Yet, it remains unclear what features of the fine-tuning data are necessary for WG to arise. Here, we address this question by investigating a range of plausibly relevant features, including dataset size, composition, language, presentation style, and novelty relative to a model's parametric knowledge. Further, since WG evaluations rely on small question sets that assess the extent of the generalization, we also analyze how sensitive this measurement is to the set of questions used. Experiments with three open-weight models on four datasets show that the degree of WG (1) depends heavily on dataset composition and language (more than on size); (2) is greater for data familiar from pretraining than for novel data; and (3) is sensiti"},{"pdf":"https://arxiv.org/pdf/2608.23242.pdf","date":"2026-08-24","title":"Mind the Couch! Eliciting MLLM Reasoning in Interior Design via Weak-to-Strong Task Vector Injection","url":"https://arxiv.org/abs/2608.23242","topics":["Reasoning","Hallucination","Evaluation","Alignment","Fine-tuning"],"authors":["Yuxuan Yang","Jingyao Wang","Luntian Mou"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.23242","id":"arxiv:2608.23242","tags":["Reasoning","Hallucination","Evaluation","Alignment","Fine-tuning"],"upvotes":0,"abstract":"Multimodal Large Language Models (MLLMs) have demonstrated great performance, yet they often suffer from severe modality misalignment when confronted with densely constrained spaces for interior design. Due to the loss of high-frequency local topological details and fine-grained aesthetic shifts during visual encoding, existing MLLMs frequently hallucinate, yielding physical spatial collisions and visual aesthetic dissonance. To address this, we propose Dual-prior Activation Residual Task-vectors Injection mechanism (DART-I) for MLLMs. It shifts the paradigm from lossy text-prompting to direct latent intervention, utilizing weak-to-strong deterministic rules to anchor the causal reasoning of MLLMs for interior design. Specifically, DART-I operates in three steps: it first explicitly extracts continuous spatial distance and color typography features from images using extremely lightweight"},{"pdf":"https://arxiv.org/pdf/2608.22950.pdf","date":"2026-08-24","title":"WADE: A Reasoning-Annotated Benchmark for Multi-Instance Floating-Waste Grounding with Compact Vision-Language Models","url":"https://arxiv.org/abs/2608.22950","topics":["VLM Training","Reasoning","Hallucination","Evaluation","Fine-tuning"],"authors":["Md. Asaduzzaman Shuvo","Ahsan Farabi","Md. Abdul Ahad Minhaz","Mahedi Hasan","Israt Khandaker","Ibrahim Khalil Shanto","Muhammad Nomani Kabir"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.22950","id":"arxiv:2608.22950","tags":["VLM Training","Reasoning","Hallucination","Evaluation","Fine-tuning"],"upvotes":0,"abstract":"Floating waste in inland waterways threatens aquatic ecosystems and requires timely monitoring under cluttered, multi-object conditions. Existing aquatic-waste datasets provide limited geographic coverage, sparse multi-instance annotations, and little supervision beyond boxes and labels. Compact vision-language models (VLMs) therefore remain insufficiently evaluated for jointly localizing, classifying, counting, and explaining floating waste. We introduce WADE, a reasoning-annotated benchmark containing 2,167 images from rural Bangladesh, 13,608 bounding boxes, and ten waste categories. Each annotation is associated with class-level recognition rules covering visual cues, likely confusions, and discriminative features. We evaluate six VLMs under zero-shot, two-shot, reasoning-guided, and fine-tuned settings using detection, counting, and hallucination metrics. For resource-efficient adap"},{"pdf":"https://arxiv.org/pdf/2608.22780.pdf","date":"2026-08-24","title":"Can We Perform Online RL for Image Editing without Editing Rewards?","url":"https://arxiv.org/abs/2608.22780","topics":["Post-Training","VLM Training","Alignment","Fine-tuning","RL for LLM"],"authors":["Qichao Ma","Jikang Cheng","Ling Liang","Zhaofei Yu","Tiejun Huang","Renye Yan"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.22780","id":"arxiv:2608.22780","tags":["Post-Training","VLM Training","Alignment","Fine-tuning","RL for LLM"],"upvotes":0,"abstract":"Reinforcement learning (RL) enables direct preference optimization for image editing through editing-specific rewards, which remain less developed due to costly triplet supervision and complex task-dependent calibration. In contrast, text-to-image (T2I) generation benefits from a mature and diverse reward ecosystem spanning semantic alignment, aesthetics, realism, glyph shape, and other visual preferences. Extending this ecosystem to image editing would substantially broaden the range of visual preferences accessible to RL-based optimization, prompting the central question: \\emph{Can We Perform Image Editing RL without Editing Rewards?} In this paper, we argue that the standard image editing dimensions have potential to be mapped to the T2I reward space: image quality can transfer directly, prompt following can be aligned through a description of the desired visual state, and reference c"},{"pdf":"https://arxiv.org/pdf/2608.20378.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"Truth Lies Deep: Countering Semantic Camouflage via Latent Intent Verification","url":"https://arxiv.org/abs/2608.20378","topics":["Agent Safety","Post-Training","LLM Training","Alignment"],"authors":["Md. Hasib Ur Rahman"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.20378","submittedDate":"2026-06-27","id":"arxiv:2608.20378","tags":["Agent Safety","Post-Training","LLM Training","Alignment"],"upvotes":0,"abstract":"Safety alignment in Large Language Models (LLMs) is often superficial, relying on refusal mechanisms that trigger only at the final stages of generation without erasing the foundational knowledge of harmful concepts acquired during pretraining. This study demonstrates that this architectural disconnect leaves models vulnerable to Semantic Camouflage -- adversarial attacks that wrap harmful intent in benign narrative contexts (e.g., creative writing), effectively bypassing standard input and output guardrails. By analyzing the latent activation trajectories of three distinct Small Language Model (SLM) families (Phi-3, Qwen2.5, and Gemma-2b) under adversarial stress, this research identifies a universal ``Intent Horizon'' -- a critical depth (typically 15--20\\% of total layers) where the model's distinct, pre-trained representation of harmful intent collapses as it contextualizes the query"},{"pdf":"https://arxiv.org/pdf/2608.21027.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"Don't Solve, Just Compare: Tiny Advisors for Runtime Intervention in LLM Agents","url":"https://arxiv.org/abs/2608.21027","topics":["Tool Use","Reasoning","Planning","Evaluation"],"authors":["Yanze Jiang","Mingxuan Li","Yuhao Wang","Shengfang Zhai","Jiaheng Zhang"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.21027","submittedDate":"2026-08-21","id":"arxiv:2608.21027","tags":["Tool Use","Reasoning","Planning","Evaluation"],"upvotes":0,"abstract":"LLM agents are emerging as an important paradigm for real-world tasks that require reasoning, tool use, and sequential decision-making. As these agents operate over longer horizons, runtime intervention offers a way to improve reliability without retraining the underlying actor. Failure detection alone is insufficient. Effective intervention must also provide a useful direction for recovery. Existing approaches often rely on an expert solver or a critic that generates task-specific corrections, incurring either the cost of another capable solver or the capacity demands of a task-capable critic. We introduce Comparison-Only Tiny Advisor (COTA), a comparison-only framework for constructive runtime intervention. In COTA, a tiny comparator judges whether sampled alternatives lead to better continuations than the actor's proposal, and repeated comparisons determine when intervention is warran"},{"pdf":"https://arxiv.org/pdf/2608.20670.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"Why2Speak: Faithful Reasoning for Abstaining Action Policies","url":"https://arxiv.org/abs/2608.20670","topics":["LLM Training","Reasoning","Fine-tuning","RL for LLM"],"authors":["Shreya Mendi","Brinnae Bent"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.20670","submittedDate":"2026-08-21","id":"arxiv:2608.20670","tags":["LLM Training","Reasoning","Fine-tuning","RL for LLM"],"upvotes":0,"abstract":"Many agentic systems must repeatedly choose between acting and abstaining, making faithful reasoning important for oversight: an explanation is useful only if it reflects the computation that produced the action. We study this problem through intervention timing in multi-party conversation, where an assistant must decide whether to speak or remain silent. This setting exposes class imbalance, asymmetric action costs, and the possibility that exposing reasoning changes the policy being audited. Using Qwen3-8B, decoded with or without chain-of-thought reasoning, we compare direct decision policies, reasoning policies, supervised fine-tuning, and reinforcement learning. We find a capability-auditability tradeoff: the strongest direct policy achieves higher quality but exposes no reasoning to inspect, while the reasoning policy provides a trace at the cost of lower performance, particularly "},{"pdf":"https://arxiv.org/pdf/2608.21100.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"ReFrame: Evidence-Guided Test-Time Safety Alignment in Multimodal Large Language Models","url":"https://arxiv.org/abs/2608.21100","topics":["Agent Safety","Reasoning","Evaluation","Alignment"],"authors":["Wenzheng Jiang","Xuankun Rong","Yuanzhao Zhai","Dawei Feng","Huaimin Wang"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.21100","submittedDate":"2026-08-21","id":"arxiv:2608.21100","tags":["Agent Safety","Reasoning","Evaluation","Alignment"],"upvotes":0,"abstract":"While multimodal large language models (MLLMs) extend model capabilities beyond text, they also make safety alignment increasingly challenging. Multimodal safety alignment methods must address cross-modal jailbreaks, safety-awareness failures, and over-sensitive refusals. However, existing methods often rely on retraining or internal-state inspection, limiting their applicability to deployed closed-source MLLMs and motivating test-time safety alignment. We analyze this setting and identify two key obstacles, utility dominance and reasoning inertia, which cause models to overlook latent risks or follow malicious reasoning trajectories. Guided by these insights, we propose ReFrame, a training-free multimodal input reframing framework where two agents share a lightweight locally deployed MLLM: the evidence-generation agent constructs complementary risk and utility evidence, and the rewrite-"},{"pdf":"https://arxiv.org/pdf/2608.20797.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"Automated Trajectory Evaluation for Mobile Agents via Step-Level Consequence Reasoning and Aggregation","url":"https://arxiv.org/abs/2608.20797","topics":["VLM Training","Reasoning","Evaluation","Alignment"],"authors":["Pengshuai Yang","Zijing Gao","Xue Yu","Benhui Zhuang","Bo Yuan","Junlan Feng"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.20797","submittedDate":"2026-08-21","id":"arxiv:2608.20797","tags":["VLM Training","Reasoning","Evaluation","Alignment"],"upvotes":0,"abstract":"Evaluating language-guided mobile agents has recently shifted from rule-based to model-based approaches to achieve scalable and automated assessments. However, existing holistic evaluation paradigms process entire trajectories at once, leading to substantial context overload. Moreover, they primarily focus on task completion while overlooking operational safety. To address these limitations, we introduce CRATE, a novel two-stage VLM-as-judge framework for automated mobile agent evaluation that is compatible with both open- and closed-source models. Leveraging a step-level consequence reasoning mechanism, CRATE independently extracts task-relevant visual clues and infers action-conditioned state changes at each step. The resulting step-level textual evidence is then synthesized through trajectory-level aggregation to deliver an evidence-grounded evaluation of task completion. Building upo"},{"pdf":"https://arxiv.org/pdf/2608.20631.pdf","date":"2026-08-24","announceDate":"2026-08-24","title":"Weighted Memory Tree: Remembering What Matters for Long-Horizon LLM Agents","url":"https://arxiv.org/abs/2608.20631","topics":["Tool Use","Reasoning","Planning","Memory"],"authors":["Quang Dao","Purvi Kathalkar","Kenneth Eaton"],"source":"arxiv","arxiv":"https://arxiv.org/abs/2608.20631","submittedDate":"2026-08-21","id":"arxiv:2608.20631","tags":["Tool Use","Reasoning","Planning","Memory"],"upvotes":0,"abstract":"Large language model (LLM) agents have demonstrated the ability to solve multi-step tasks requiring planning, tool use, and external information access, yet growing execution histories increase inference cost and expose reasoning to outdated, irrelevant, or misleading information, potentially degrading reasoning quality. Existing memory approaches organize or compress execution histories but provide limited mechanisms for deciding which memories remain active. We introduce the, a hierarchical memory system that organizes execution into tasks, subtasks, and actions while assigning each memory a dynamic retention score. Event-based updates and selection-based decay revise these scores, allowing WMT to preserve useful information, fold completed trajectories, suppress low-utility content, and retain access to folded context. We evaluate WMT on GAIA-Text using Qwen3-8B, Gemma 4 E4B, and Llam"}],"archive":[],"latestPath":"data/latest.json"};
